pe":"tapcanvas.chapter-asset-plan/v3","workflowAgentToolPolicy":"none","workflowPermission":{"visibilityRoles":["admin"],"editRoles":["admin"],"runRoles":["admin"]},"adminWorkflow":true,"kind":"workflowStage","status":"idle","nodeWidth":56,"nodeHeight":56}},{"id":"builtin-video-production-v114:clip-production-pipeline","type":"taskNode","parentId":"builtin-video-production-v114:group","position":{"x":448,"y":192},"data":{"label":"全章 Clip 提示词与节点规划","workflowKey":"one-click-production/v1","workflowDefinitionVersion":1,"workflowCanvasDefinitionVersion":114,"workflowCanvasDefinitionFingerprint":"sha256:e1ef5f3fa343c832b4d0bbb8e0ac1bc8fffa407dca32e40abf3a777c36a6cb74","workflowInstanceId":"builtin-video-production-v114","workflowExecutionScope":"media_delivery","workflowExecutionVariant":"full_video","workflowNodeId":"clip-production-pipeline","workflowNodeKind":"inline_pipeline","workflowAtomicSpec":{"version":1,"category":"subworkflow","operation":"inline_pipeline","executorRef":"workflow.pipeline.run/v1","executionMode":"once","inputPorts":["delivery-contract","source-segments","clip-sequences","chapter-assets"],"outputPorts":["node-plan","prompt-package","media-items","prepared-nodes"],"inputArtifactTypes":{"delivery-contract":["tapcanvas.delivery-contract/v2"],"source-segments":["tapcanvas.clip-source-segments/v1"],"clip-sequences":["tapcanvas.chapter-sequence-clips/v1"],"chapter-assets":["tapcanvas.chapter-asset-plan/v3"]},"outputArtifactTypes":{"node-plan":["tapcanvas.clip-production-node-plan/v1"],"prompt-package":["tapcanvas.prompt-package/v2"],"media-items":["tapcanvas.clip-production-media-items/v1"],"prepared-nodes":["tapcanvas.video-node/v1"]}},"workflowInputPorts":["delivery-contract","source-segments","clip-sequences","chapter-assets"],"workflowOptionalInputPorts":[],"workflowOutputPorts":["node-plan","prompt-package","media-items","prepared-nodes"],"workflowOperationDescription":"逐 Clip 并行调用带 Skill 与知识检索的视频提示词 Agent；全章去重共享图像资产，持久化一 Clip 一视频节点和依赖边并回读。","workflowPipeline":{"protocolVersion":"workflow.pipeline.run/v1","inputs":[{"portId":"delivery-contract","mode":"value","artifactTypes":["tapcanvas.delivery-contract/v2"]},{"portId":"source-segments","mode":"collection","artifactTypes":["tapcanvas.clip-source-segments/v1"]},{"portId":"clip-sequences","mode":"collection","artifactTypes":["tapcanvas.chapter-sequence-clips/v1"]},{"portId":"chapter-assets","mode":"value","artifactTypes":["tapcanvas.chapter-asset-plan/v3"]}],"steps":[{"stepId":"clip-production-agent","node":{"id":"clip-production-agent","type":"taskNode","kind":"workflowStage","data":{"kind":"workflowStage","label":"逐 Clip 提示词与资产意图","workflowNodeId":"clip-production-agent","workflowNodeKind":"clip_production_authoring","workflowAtomicSpec":{"version":1,"category":"agent","operation":"clip_production_authoring","executorRef":"agents.logical-task/v2","executionMode":"each","inputPorts":["clip-segment","clip-sequence","delivery-contract","chapter-assets"],"outputPorts":["packets"],"inputArtifactTypes":{"clip-segment":["tapcanvas.clip-source-segments/v1","tapcanvas.clip-source-segment/v1"],"clip-sequence":["tapcanvas.chapter-sequence-clips/v1","tapcanvas.chapter-sequence-clip/v1"],"delivery-contract":["tapcanvas.delivery-contract/v2"],"chapter-assets":["tapcanvas.chapter-asset-plan/v3"]},"outputArtifactTypes":{"packets":["tapcanvas.clip-production-packet/v1"]},"itemConcurrency":16},"workflowInputPorts":["clip-segment","clip-sequence","delivery-contract","chapter-assets"],"workflowOptionalInputPorts":[],"workflowOutputPorts":["packets"],"workflowOperationDescription":"按冻结来源集合逐 Clip 并行创作完整视频提示词、明确输入模式与图像资产意图；保留逐 Clip 身份和来源，不编造资产 URL。","workflowExecutionScope":"media_delivery","workflowExecutionVariant":"full_video","workflowInstruction":"依据已冻结 chapter-assets.objectRegistry 的精确 objectId、身份事实、现有资产选择和图像计划，以及 clip-sequence 的本段起止状态、相邻段交接、事件时间轴和逐字投影对白，为收到的每个 clip-segment 独立创作完整可执行视频提示词。实际入镜的同一对象跨 Clip 必须引用同一个 registryObjectId；assetId 与 state 区分同一对象的不同画面状态，不得因 Clip 不同重复创造人物或场景身份。每个 assetIntent 只选择章级 registryObjectId 和与其一致的 imageSource：章级 reuse 只提交 {mode:\"reuse\",registryAssetIndex}，索引从该对象 imageSource.assetIds 零起；章级 generate 只提交 {mode:\"generate\"}。共享图片身份、语义名称、参考职责、卡片元数据和生图提示词都由宿主从冻结章级计划原样投影，逐 Clip 不再重写 assetId、state、generationSpec 或长已有资产 ID；局部服装、动作与画面状态写进本段视频提示词。按冻结 delivery-contract 填写 imageModelKey、imageAspectRatio、imageSize，不猜模型参数。blockingPlan 明确本段可见人物、地标、机位与构图；使用 backgroundPlanIndex 从冻结章级 backgroundPlans 零起选择背景，不抄写 backgroundObjectId。它是空间调度事实，不冒充已生成的站位图。通过同媒体视频案例候选回执按需读取正文；零命中或检索失败记录证据后继续原创，不伪称引用。protocolVersion、clipId、clipIndex、durationSeconds、sourceRanges 必须保留冻结值；clipFacts.sequenceClipId 必须填写本段冻结 clipId。依据供应商能力与创作需求选择明确支持的 videoInputMode；只提交 firstFrameAssetIndex（没有首帧时 null）和 referenceAssetIndices，从本 packet 的 assetIntents 零起选择；宿主派生 assetId 与 state，不重复抄写。image_to_video 的首帧索引必须同时包含在引用索引中；reference_to_video 必须提供引用；text_to_video 不得虚构图像依赖。模型参数只继承本轮显式选择或账号偏好与实时目录，不猜默认值或切换模型。提交前核对本 Clip 引用的图像身份均在冻结章级注册表中，节点与媒体阶段随后解析真实 URL；不得假称已生成资产或改写来源范围。","workflowAgentOutputEncoding":"json_object","workflowAgentJsonObjectContract":{"allowedFields":["protocolVersion","clipId","clipIndex","durationSeconds","videoInputMode","firstFrameAsset","referenceAssets","sourceRanges","videoPrompt","blockingPlan","clipFacts","assetIntents"],"jsonSchema":{"type":"object","properties":{"protocolVersion":{"type":"string","const":"tapcanvas.clip-production-packet/v1"},"clipId":{"type":"string","minLength":1,"pattern":"^\\S(?:[\\s\\S]*\\S)?$"},"clipIndex":{"type":"integer","minimum":0,"maximum":79},"durationSeconds":{"type":"integer","minimum":1},"videoInputMode":{"type":"string","enum":["image_to_video","reference_to_video","text_to_video"]},"firstFrameAsset":{"oneOf":[{"type":"object","properties":{"assetId":{"type":"string","minLength":1,"pattern":"^\\S(?:[\\s\\S]*\\S)?$"},"state":{"type":"string","minLength":1,"pattern":"^\\S(?:[\\s\\S]*\\S)?$"}},"required":["assetId","state"],"additionalProperties":false},{"type":"null"}]},"referenceAssets":{"type":"array","i